package com.benbenyu.btquicklaunch;
import android.content.*;import android.hardware.*;import android.media.*;import android.os.*;import android.view.*;import java.lang.ref.WeakReference;
/** Foreground-only idle dimming using Android input/audio/motion lifecycle APIs. */
final class IdlePower {
 static WeakReference<IdlePower> current=new WeakReference<>(null);final MainActivity activity;final Handler h=new Handler();final AudioManager audio;final SensorManager sensors;Sensor motion;boolean started,dimmed;long lastActivity;View shade;
 IdlePower(MainActivity a){activity=a;audio=(AudioManager)a.getSystemService(Context.AUDIO_SERVICE);sensors=(SensorManager)a.getSystemService(Context.SENSOR_SERVICE);}
 static void externalInput(){IdlePower power=current.get();if(power!=null)power.h.post(()->power.activity("hid_input"));}
 final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent in){activity("external_event");}};
 final AudioManager.AudioPlaybackCallback playback=new AudioManager.AudioPlaybackCallback(){public void onPlaybackConfigChanged(java.util.List<AudioPlaybackConfiguration> configs){if(audio.isMusicActive())activity("audio_playback");}};
 final TriggerEventListener movement=new TriggerEventListener(){public void onTrigger(TriggerEvent event){h.post(()->{activity("significant_motion");if(started&&motion!=null)sensors.requestTriggerSensor(movement,motion);});}};
 void attach(View v){shade=v;if(dimmed)shade.setAlpha(.82f);}
 void start(){if(started)return;started=true;current=new WeakReference<>(this);lastActivity=SystemClock.elapsedRealtime();IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_HEADSET_PLUG);f.addAction(Intent.ACTION_POWER_CONNECTED);f.addAction(Intent.ACTION_POWER_DISCONNECTED);f.addAction("android.hardware.usb.action.USB_DEVICE_ATTACHED");f.addAction("android.hardware.usb.action.USB_DEVICE_DETACHED");activity.registerReceiver(receiver,f);audio.registerAudioPlaybackCallback(playback,h);motion=sensors.getDefaultSensor(Sensor.TYPE_SIGNIFICANT_MOTION);if(motion!=null)sensors.requestTriggerSensor(movement,motion);h.post(tick);}
 void stop(){if(!started)return;started=false;current.clear();h.removeCallbacksAndMessages(null);try{activity.unregisterReceiver(receiver);}catch(Exception ignored){}audio.unregisterAudioPlaybackCallback(playback);if(motion!=null)sensors.cancelTriggerSensor(movement,motion);setDim(false);}
 void activity(String reason){if(!started)return;lastActivity=SystemClock.elapsedRealtime();if(dimmed){AppLog.write("IDLE_WAKE "+reason,null);setDim(false);}}
 void setDim(boolean dim){if(dimmed==dim)return;dimmed=dim;WindowManager.LayoutParams params=activity.getWindow().getAttributes();int normal=activity.p.getInt("brightness",0);params.screenBrightness=dim?.01f:normal==0?-1f:Math.max(.05f,normal/100f);activity.getWindow().setAttributes(params);if(activity.settingsDialog!=null&&activity.settingsDialog.isShowing()){WindowManager.LayoutParams dialog=activity.settingsDialog.getWindow().getAttributes();dialog.screenBrightness=params.screenBrightness;activity.settingsDialog.getWindow().setAttributes(dialog);}if(shade!=null)shade.setAlpha(dim?.82f:0f);AppLog.write(dim?"IDLE_DIM":"IDLE_NORMAL",null);}
 final Runnable tick=new Runnable(){public void run(){if(!started)return;boolean enabled=activity.p.getBoolean("idle_power",true);if(!enabled)setDim(false);else{if(audio.isMusicActive())activity("audio_active");if(SystemClock.elapsedRealtime()-lastActivity>=120000)setDim(true);}h.postDelayed(this,10000);}};
}
